const { World, setWorldConstructor } = require('@cucumber/cucumber');
const { JSDOM } = require('jsdom');
const fs = require('fs');
const path = require('path');

class TodoWorld extends World {
  constructor() {
    super();
    this.dom = null;
    this.document = null;
    this.window = null;
  }

  async loadApp() {
    const htmlPath = path.join(__dirname, '../../assets/app-template.index.html');
    const html = fs.readFileSync(htmlPath, 'utf8');

    // Create JSDOM instance
    this.dom = new JSDOM(html, {
      url: 'http://localhost',
      runScripts: 'dangerously',
      resources: 'usable',
      pretendToBeVisual: true,
    });

    this.window = this.dom.window;
    this.document = this.window.document;

    // Wait for scripts to load
    await new Promise(resolve => setTimeout(resolve, 100));
  }
}

setWorldConstructor(TodoWorld);

const { Given, When, Then } = require('@cucumber/cucumber');
const { expect } = require('chai');

Given('the todo app is loaded', async function () {
  await this.loadApp();
});

Then('the new todo input is visible', function () {
  const input = this.document.querySelector('.new-todo');
  expect(input).to.not.be.null;
  expect(input.style.display).to.not.equal('none');
});

Then('the main section is hidden', function () {
  const main = this.document.querySelector('.main');
  expect(main).to.not.be.null;
  expect(main.style.display).to.equal('none');
});

Then('the footer is hidden', function () {
  const footer = this.document.querySelector('.footer');
  expect(footer).to.not.be.null;
  expect(footer.style.display).to.equal('none');
});

When('the user types {string} in the new todo input and presses Enter', function (text) {
  const input = this.document.querySelector('.new-todo');
  input.value = text;
  const event = new this.window.KeyboardEvent('keydown', {
    key: 'Enter',
    code: 'Enter',
    keyCode: 13,
    which: 13,
  });
  input.dispatchEvent(event);
});

Then('the todo list contains {int} item', function (count) {
  const items = this.document.querySelectorAll('.todo-list li');
  expect(items.length).to.equal(count);
});

Then('the todo list contains {float} item', function (count) {
  const items = this.document.querySelectorAll('.todo-list li');
  expect(items.length).to.equal(count);
});

Then('the todo at position {int} has title {string}', function (position, title) {
  const items = this.document.querySelectorAll('.todo-list li');
  const item = items[position - 1];
  expect(item).to.not.be.null;
  const label = item.querySelector('label');
  expect(label.textContent).to.equal(title);
});

Then('the todo at position {float} has title {string}', function (position, title) {
  const items = this.document.querySelectorAll('.todo-list li');
  const item = items[position - 1];
  expect(item).to.not.be.null;
  const label = item.querySelector('label');
  expect(label.textContent).to.equal(title);
});

Then('the todo at position {int} is not completed', function (position) {
  const items = this.document.querySelectorAll('.todo-list li');
  const item = items[position - 1];
  expect(item).to.not.be.null;
  expect(item.classList.contains('completed')).to.be.false;
});

Then('the todo at position {float} is not completed', function (position) {
  const items = this.document.querySelectorAll('.todo-list li');
  const item = items[position - 1];
  expect(item).to.not.be.null;
  expect(item.classList.contains('completed')).to.be.false;
});

Then('the new todo input is empty', function () {
  const input = this.document.querySelector('.new-todo');
  expect(input.value).to.equal('');
});

When('the user presses Enter in the new todo input', function () {
  const input = this.document.querySelector('.new-todo');
  const event = new this.window.KeyboardEvent('keydown', {
    key: 'Enter',
    code: 'Enter',
    keyCode: 13,
    which: 13,
  });
  input.dispatchEvent(event);
});

Then('the todo list contains {int} items', function (count) {
  const items = this.document.querySelectorAll('.todo-list li');
  expect(items.length).to.equal(count);
});

Then('the todo list contains {float} items', function (count) {
  const items = this.document.querySelectorAll('.todo-list li');
  expect(items.length).to.equal(count);
});

Then('the main section is visible', function () {
  const main = this.document.querySelector('.main');
  expect(main).to.not.be.null;
  expect(main.style.display).to.not.equal('none');
});

Then('the footer is visible', function () {
  const footer = this.document.querySelector('.footer');
  expect(footer).to.not.be.null;
  expect(footer.style.display).to.not.equal('none');
});

