(function () {
	'use strict';

	var newTodoInput = document.querySelector('.new-todo');
	var todoList = document.querySelector('.todo-list');
	var mainSection = document.querySelector('.main');
	var footerSection = document.querySelector('.footer');

	// Hide main and footer initially
	mainSection.style.display = 'none';
	footerSection.style.display = 'none';

	// Handle new todo creation
	newTodoInput.addEventListener('keydown', function (e) {
		if (e.key === 'Enter' || e.keyCode === 13) {
			var title = newTodoInput.value.trim();
			if (title) {
				addTodo(title);
				newTodoInput.value = '';
			}
		}
	});

	function addTodo(title) {
		var li = document.createElement('li');
		li.innerHTML = '<div class="view">' +
			'<input class="toggle" type="checkbox">' +
			'<label>' + escapeHtml(title) + '</label>' +
			'<button class="destroy"></button>' +
			'</div>' +
			'<input class="edit" value="' + escapeHtml(title) + '">';
		todoList.appendChild(li);
		updateUI();
	}

	function updateUI() {
		var todos = todoList.querySelectorAll('li');
		if (todos.length > 0) {
			mainSection.style.display = '';
			footerSection.style.display = '';
		} else {
			mainSection.style.display = 'none';
			footerSection.style.display = 'none';
		}
	}

	function escapeHtml(text) {
		var div = document.createElement('div');
		div.appendChild(document.createTextNode(text));
		return div.innerHTML;
	}
})();

