// Store the addTodo function for testing
    this.addTodo = (title) => {
      const todoList = this.document.querySelector('.todo-list');
      const mainSection = this.document.querySelector('.main');
      const footerSection = this.document.querySelector('.footer');

      if (title) {
        const li = this.document.createElement('li');
        li.innerHTML = '<div class="view">' +
          '<input class="toggle" type="checkbox">' +
          '<label>' + this.escapeHtml(title) + '</label>' +
          '<button class="destroy"></button>' +
          '</div>' +
          '<input class="edit" value="' + this.escapeHtml(title) + '">';
        todoList.appendChild(li);

        // Update UI
        const todos = todoList.querySelectorAll('li');
        if (todos.length > 0) {
          mainSection.style.display = '';
          footerSection.style.display = '';
        } else {
          mainSection.style.display = 'none';
          footerSection.style.display = 'none';
        }
      }
    };

    this.escapeHtml = (text) => {
      const div = this.document.createElement('div');
      div.appendChild(this.document.createTextNode(text));
      return div.innerHTML;
    };

