function addTodo(title) {
		var li = document.createElement('li');
		li.innerHTML = '<div class="view">' +
			'<input class="toggle" type="checkbox">' +
			'<label>' + escapeHtml(title) + '</label>' +
			'<button class="destroy"></button>' +
			'</div>' +
			'<input class="edit" value="' + escapeHtml(title) + '">';
		todoList.appendChild(li);
		updateUI();
	}

	// Event delegation for todo items
	todoList.addEventListener('click', function (e) {
		var target = e.target;
		var li = target.closest('li');
		if (!li) return;

		// Toggle checkbox
		if (target.classList.contains('toggle')) {
			li.classList.toggle('completed', target.checked);
		}

		// Destroy button
		if (target.classList.contains('destroy')) {
			li.remove();
			updateUI();
		}
	});

	// Double-click for editing
	todoList.addEventListener('dblclick', function (e) {
		var target = e.target;
		if (target.tagName === 'LABEL') {
			var li = target.closest('li');
			if (li) {
				li.classList.add('editing');
				var editInput = li.querySelector('.edit');
				editInput.focus();
			}
		}
	});

	// Edit input handling
	todoList.addEventListener('keydown', function (e) {
		var target = e.target;
		if (target.classList.contains('edit')) {
			var li = target.closest('li');
			if (!li) return;

			if (e.key === 'Enter') {
				target.blur();
			} else if (e.key === 'Escape') {
				target.value = li.querySelector('label').textContent;
				target.blur();
			}
		}
	});

	todoList.addEventListener('blur', function (e) {
		var target = e.target;
		if (target.classList.contains('edit')) {
			var li = target.closest('li');
			if (!li) return;

			var title = target.value.trim();
			if (title) {
				li.querySelector('label').textContent = title;
				target.value = title;
			} else {
				li.remove();
				updateUI();
			}
			li.classList.remove('editing');
		}
	}, true);

