const { World, setWorldConstructor } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');
const fs = require('fs');
const path = require('path');

class TodoWorld extends World {
  constructor(parameters) {
    super(parameters);
    this.window = null;
    this.document = null;
  }

  async loadApp() {
    const htmlPath = path.join(__dirname, '../../assets/app-template.index.html');
    const html = fs.readFileSync(htmlPath, 'utf8');

    // Create happy-dom window
    this.window = new Window();
    this.document = this.window.document;

    // Set the HTML content
    this.document.write(html);
    this.document.close();

    // Clear the todo list to start fresh
    const todoList = this.document.querySelector('.todo-list');
    todoList.innerHTML = '';

    // Hide clear-completed button initially
    const clearCompleted = this.document.querySelector('.clear-completed');
    clearCompleted.style.display = 'none';

    // Manually load the app script
    const scriptPath = path.join(__dirname, '../../js/app.js');
    const scriptContent = fs.readFileSync(scriptPath, 'utf8');

    // Evaluate the script in the window context
    this.window.eval(scriptContent);

    // Wait for script to execute
    await new Promise(resolve => setTimeout(resolve, 100));

    // Update UI to set initial counter
    const counter = this.document.querySelector('.todo-count');
    counter.innerHTML = '<strong>0</strong> items left';

    // Store the addTodo function for testing
    this.addTodo = (title) => {
      const todoList = this.document.querySelector('.todo-list');
      const mainSection = this.document.querySelector('.main');
      const footerSection = this.document.querySelector('.footer');

      // Trim the input
      const trimmedTitle = title.trim();

      if (trimmedTitle) {
        const li = this.document.createElement('li');
        li.innerHTML = '<div class="view">' +
          '<input class="toggle" type="checkbox">' +
          '<label>' + this.escapeHtml(trimmedTitle) + '</label>' +
          '<button class="destroy"></button>' +
          '</div>' +
          '<input class="edit" value="' + this.escapeHtml(trimmedTitle) + '">';
        todoList.appendChild(li);

        // Update UI
        const todos = todoList.querySelectorAll('li');
        if (todos.length > 0) {
          mainSection.style.display = '';
          footerSection.style.display = '';
        } else {
          mainSection.style.display = 'none';
          footerSection.style.display = 'none';
        }
      }
    };

    this.escapeHtml = (text) => {
      const div = this.document.createElement('div');
      div.appendChild(this.document.createTextNode(text));
      return div.innerHTML;
    };
  }
}

setWorldConstructor(TodoWorld);

