const { Given, When, Then } = require('@cucumber/cucumber');
const { expect } = require('chai');

Given('the user has completed the todo {string}', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (const item of items) {
    const label = item.querySelector('label');
    if (label.textContent === title) {
      const checkbox = item.querySelector('.toggle');
      checkbox.click();
      break;
    }
  }
});

When('the user navigates to {string}', function (route) {
  // Simulate navigation by changing the hash
  this.window.location.hash = route;

  // Trigger the hashchange event
  const event = this.document.createEvent('Event');
  event.initEvent('hashchange', true, true);
  this.window.dispatchEvent(event);
});

Then('the todo list shows {int} item', function (count) {
  const items = this.document.querySelectorAll('.todo-list li');
  expect(items.length).to.equal(count);
});

Then('the todo list shows {int} items', function (count) {
  const items = this.document.querySelectorAll('.todo-list li');
  expect(items.length).to.equal(count);
});

Then('the todo {string} is visible in the list', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  let found = false;
  for (const item of items) {
    const label = item.querySelector('label');
    if (label.textContent === title) {
      found = true;
      break;
    }
  }
  expect(found).to.be.true;
});

Then('the {string} filter link is selected', function (filterName) {
  const filters = this.document.querySelectorAll('.filters a');
  let selected = false;
  for (const filter of filters) {
    if (filter.textContent === filterName && filter.classList.contains('selected')) {
      selected = true;
      break;
    }
  }
  expect(selected).to.be.true;
});

