	// Routing
	function getRoute() {
		return window.location.hash || '#/';
	}

	function applyFilter() {
		var route = getRoute();
		var todos = todoList.querySelectorAll('li');
		todos.forEach(function (li) {
			var isCompleted = li.classList.contains('completed');
			if (route === '#/active') {
				li.style.display = isCompleted ? 'none' : '';
			} else if (route === '#/completed') {
				li.style.display = isCompleted ? '' : 'none';
			} else {
				li.style.display = '';
			}
		});

		// Update filter links
		var filters = document.querySelectorAll('.filters a');
		filters.forEach(function (filter) {
			filter.classList.remove('selected');
			if (filter.getAttribute('href') === route) {
				filter.classList.add('selected');
			}
		});
	}

	// Listen for hash changes
	window.addEventListener('hashchange', applyFilter);

	// Apply filter on initial load
	applyFilter();

