arguments.content:
const { Given, When, Then } = require('@cucumber/cucumber');
const { expect } = require('chai');

When('the page is reloaded', function () {
  // Save the current todos to localStorage
  const todos = [];
  const items = this.document.querySelectorAll('.todo-list li');
  items.forEach(function (item) {
    const label = item.querySelector('label');
    const checkbox = item.querySelector('.toggle');
    todos.push({
      title: label.textContent,
      completed: checkbox.checked
    });
  });

  // Save to localStorage
  this.window.localStorage.setItem('todos', JSON.stringify(todos));

  // Reload the app
  this.loadApp();

  // Load todos from localStorage
  const savedTodos = JSON.parse(this.window.localStorage.getItem('todos') || '[]');
  savedTodos.forEach(function (todo) {
    this.addTodo(todo.title);
    if (todo.completed) {
      // Mark as completed
      const items = this.document.querySelectorAll('.todo-list li');
      const lastItem = items[items.length - 1];
      const checkbox = lastItem.querySelector('.toggle');
      checkbox.click();
    }
  }.bind(this));
});

